document.documentElement.classList.add('js');
const menuButton=document.querySelector('.menu-button');
const menu=document.querySelector('#mobile-nav');
function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Öppna menyn');document.body.classList.remove('locked');document.querySelector('main').inert=false}
menuButton.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Stäng menyn':'Öppna menyn');document.body.classList.toggle('locked',open);document.querySelector('main').inert=open;if(open)menu.querySelector('a').focus()});
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.querySelector('.header .brand').addEventListener('click',closeMenu);
document.addEventListener('keydown',e=>{if(menu.hidden)return;if(e.key==='Escape'){closeMenu();menuButton.focus()}if(e.key==='Tab'){const items=[menuButton,...menu.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}});
const services={
flyttstad:{label:'Flyttstädning',title:'Lämna rent.\nBörja på nytt.',description:'En flytt är tillräckligt mycket att tänka på. Låt oss ta hand om städningen medan du kommer på plats i ditt nya hem.',image:'cleaning',alt:'Fönster rengörs noggrant med en fönsterskrapa',list:['För lägenheter och villor','Genomgång av resultatet','Nöjd kund-garanti'],cta:'Fråga om flyttstädning'},
hemstad:{label:'Hemstädning',title:'Kom hem.\nOch känn dig ledig.',description:'Ibland räcker tiden inte till. Vi hjälper dig med städningen hemma och kommer överens om vad just ditt hem behöver.',image:'hero',alt:'Ett ljust och välordnat vardagsrum',list:['Städning utifrån ditt behov','Omtanke om ditt hem','Genomgång före godkännande'],cta:'Fråga om hemstädning'},
bygg:{label:'Bygg & måleri',title:'Nya ytor.\nNya möjligheter.',description:'Måleri, tapetsering, mindre snickeri och golvarbeten. Vi hjälper även till med montering och renovering av kök och badrum. Berätta om dina planer.',image:'painting',alt:'En hand målar en ljus vägg med roller',list:['Måleri inne och ute','Golv, kakel och klinker','Möbler, skåp och VVS-montering'],cta:'Berätta om ditt byggprojekt'},
foretag:{label:'Företagsservice',title:'Ta hand om jobbet.\nVi tar hand om lokalen.',description:'Låt arbetsplatsen få samma omsorg som hemmet. Vi erbjuder kontorsstädning, måleri och mindre byggarbeten för företag i Örebro län.',image:'cleaning',alt:'Noggrann rengöring av ett stort fönster',list:['Kontorsstädning','Måleri och byggservice','En kontakt för era behov'],cta:'Fråga om företagsservice'}
};
const tabs=[...document.querySelectorAll('[data-service]')];
function chooseService(key){if(!services[key])return;const data=services[key];tabs.forEach(tab=>{const active=tab.dataset.service===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1});const panel=document.querySelector('#service-panel');panel.setAttribute('aria-labelledby','tab-'+key);document.querySelector('#service-title').textContent=data.title;document.querySelector('#service-title').style.whiteSpace='pre-line';document.querySelector('#service-description').textContent=data.description;const img=document.querySelector('#service-image');img.src='assets/'+data.image+'.webp';img.srcset='assets/'+data.image+'-small.webp 800w, assets/'+data.image+'.webp '+(data.image==='hero'?1672:1448)+'w';img.alt=data.alt;const list=document.querySelector('#service-list');list.replaceChildren(...data.list.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));const cta=document.querySelector('#service-quote');cta.textContent=data.cta;cta.dataset.quote=data.label;panel.classList.remove('changing');requestAnimationFrame(()=>panel.classList.add('changing'))}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>chooseService(tab.dataset.service));tab.addEventListener('keydown',e=>{let next=index;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();tabs[next].focus();chooseService(tabs[next].dataset.service)})});
document.querySelectorAll('[data-select-service]').forEach(a=>a.addEventListener('click',()=>chooseService(a.dataset.selectService)));
const quote=document.querySelector('#quote-dialog');
const quoteForm=document.querySelector('#quote-form');
const quoteEdit=document.querySelector('#quote-edit');
const quoteReview=document.querySelector('#quote-review');
let draftText='';
function openQuote(service){closeMenu();if([...document.querySelector('#quote-service').options].some(o=>o.value===service))document.querySelector('#quote-service').value=service;quoteEdit.hidden=false;quoteReview.hidden=true;quote.setAttribute('aria-labelledby','quote-title');quote.removeAttribute('aria-label');quote.showModal();document.body.classList.add('locked')}
document.querySelector('#quick-quote').addEventListener('submit',e=>{e.preventDefault();openQuote(document.querySelector('#quick-service').value)});
document.querySelectorAll('[data-quote]').forEach(b=>b.addEventListener('click',()=>openQuote(b.dataset.quote||document.querySelector('#quick-service').value)));
quoteForm.addEventListener('submit',e=>{e.preventDefault();if(!quoteForm.reportValidity())return;const data=new FormData(quoteForm);const service=String(data.get('service'));draftText='Hej!\n\nJag vill gärna få en kostnadsfri offert för '+service.toLocaleLowerCase('sv-SE')+'.\n\nOrt: '+String(data.get('city')).trim()+'\n\n'+String(data.get('message')).trim()+'\n\nVänliga hälsningar,\n'+String(data.get('name')).trim()+'\nE-post: '+String(data.get('email')).trim()+(data.get('phone')?'\nTelefon: '+String(data.get('phone')).trim():'');document.querySelector('#quote-summary').textContent=draftText;document.querySelector('#email-draft').href='mailto:info@sflytthemservice.se?subject='+encodeURIComponent('Offertförfrågan: '+service)+'&body='+encodeURIComponent(draftText);document.querySelector('#copy-status').textContent='';quoteEdit.hidden=true;quoteReview.hidden=false;quote.setAttribute('aria-label','Din offertförfrågan är förberedd');quote.removeAttribute('aria-labelledby');quote.scrollTop=0;document.querySelector('#email-draft').focus()});
document.querySelector('#quote-back').addEventListener('click',()=>{quoteReview.hidden=true;quoteEdit.hidden=false;quote.setAttribute('aria-labelledby','quote-title');quote.removeAttribute('aria-label');document.querySelector('#quote-service').focus()});
document.querySelector('#copy-draft').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(draftText);status.textContent='Texten är kopierad. Klistra in den i ett mejl till info@sflytthemservice.se.'}catch{const range=document.createRange();range.selectNodeContents(document.querySelector('#quote-summary'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);status.textContent='Markeringen är klar. Kopiera texten med Ctrl+C eller Cmd+C.'}});
document.querySelector('#privacy-open').addEventListener('click',()=>{document.querySelector('#privacy-dialog').showModal();document.body.classList.add('locked')});
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('locked'));dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))dialog.close()})});
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const params=new URLSearchParams(location.search);if(params.has('service'))chooseService(params.get('service'));if(params.get('quote')==='1')openQuote('Flyttstädning');
